// GQ has no coalesce or case/if expression, so "unknown" and the
// "senior"/"active" labels cannot be produced directly. This is the closest
// expressible form: city is null when missing, and the age test comes back
// as a boolean. The caller maps null to "unknown" and true to "senior",
// false to "active". A null age gives a null `is_senior`.
query person_bands() {
    match {
        $p: Person
    }
    return {
        $p.name,
        $p.city,
        $p.age >= 65 as is_senior
    }
}
